# Install-Ams-Sla-DayEnd-OneShot.ps1
# Self-contained. Copy this ONE file to the APP server and run elevated:
#   powershell -NoProfile -ExecutionPolicy Bypass -File C:\RPM-Assure\deploy\Install-Ams-Sla-DayEnd-OneShot.ps1
$ErrorActionPreference = 'Stop'
$App = 'C:\RPM-Assure\App'
$Svc = 'RPMAssure-App'
$Port = 8081
$Work = 'C:\RPM-Assure\deploy\ams-sla-dayend-extract'

function W($c,$m){ Write-Host $m -ForegroundColor $c }
Write-Host '========================================' -ForegroundColor Cyan
Write-Host ' RPM Assure - AMS / SLA / Day-end one-shot'
Write-Host '========================================' -ForegroundColor Cyan

$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).
  IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) { throw 'Run as Administrator.' }
if (-not (Test-Path $App)) { throw "Missing $App" }

