'@

if (Test-Path $Work) { Remove-Item $Work -Recurse -Force }
New-Item -ItemType Directory -Force -Path $Work | Out-Null
$zip = Join-Path $Work 'pack.zip'
[IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String(($b64 -replace '\s','')))
Expand-Archive -LiteralPath $zip -DestinationPath $Work -Force
$src = Join-Path $Work 'src'
if (-not (Test-Path $src)) { throw 'Extract failed — src missing.' }

$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$bak = "C:\RPM-Assure\backup\ams-sla-dayend_$stamp"
New-Item -ItemType Directory -Force -Path $bak | Out-Null
Get-ChildItem $src -Recurse -File | ForEach-Object {
  $rel = $_.FullName.Substring($src.Length).TrimStart('\')
  $existing = Join-Path (Join-Path $App 'src') $rel
  if (Test-Path -LiteralPath $existing) {
    $dest = Join-Path (Join-Path $bak 'src') $rel
    New-Item -ItemType Directory -Force -Path (Split-Path $dest) | Out-Null
    Copy-Item -LiteralPath $existing -Destination $dest -Force
  }
}
W Green "Backup $bak"
Copy-Item -Path (Join-Path $src '*') -Destination (Join-Path $App 'src') -Recurse -Force
W Green 'Source copied'

$svc = Get-Service -Name $Svc -ErrorAction SilentlyContinue
if ($svc) {
  W Cyan "Restart-Service $Svc ..."
  Restart-Service -Name $Svc -Force
  $up = $false
  for ($i = 1; $i -le 40; $i++) {
    Start-Sleep -Seconds 1
    $l = Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue
    if ($l) { W Green ("LISTENING PID {0}" -f $l[0].OwningProcess); $up = $true; break }
  }
  if (-not $up) { throw "Service restarted but port $Port not listening." }
  Get-Service $Svc | Format-Table Name, Status, StartType -AutoSize
} else {
  W Yellow 'Service RPMAssure-App not found — files copied.'
}

try {
  $r = Invoke-WebRequest -Uri "http://127.0.0.1:$Port/login" -UseBasicParsing -TimeoutSec 8
  W Green ("PROOF OK: /login HTTP {0}" -f $r.StatusCode)
} catch {
  W Yellow ("PROOF: /login not ready — $($_.Exception.Message)")
}

Write-Host ''
Write-Host ' INSTALLED — hard-refresh the browser' -ForegroundColor Green
Write-Host '  SLA page = RPM clocks (no 99.5%)'
Write-Host '  SYSPRO → Day end'
Write-Host '  Assure pack → Print monthly AMS pack'
